module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [31:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 0;
        valid_out <= 0;
    end else begin
        if (valid_in) begin
            sum <= sum + {data_in, 2'b0};
        end
        if (sum[9:0] != 0 && sum[9:0] != 10'd256 && sum[9:0] != 10'd512 && sum[9:0] != 10'd768) begin
            data_out <= sum[9:0];
            valid_out <= 1;
        end else begin
            valid_out <= 0;
        end
    end
end

endmodule
